def read_stringnl(f, decode=True, stripquotes=True, *, encoding='latin-1'):

    data = f.readline()
    if not data.endswith(b'\n'):
        raise ValueError("no newline found when trying to read stringnl")
    data = data[:-1]    # lose the newline

    if stripquotes:
        for q in (b'"', b"'"):
            if data.startswith(q):
                if not data.endswith(q):
                    raise ValueError("string quote %r not found at both "
                                     "ends of %r" % (q, data))
                data = data[1:-1]
                break
        else:
            raise ValueError("no string quotes around %r" % data)

    if decode:
        data = codecs.escape_decode(data)[0].decode(encoding)
    return data

def lazycache(filename, module_globals):
    entry = cache.get(filename, None)
    if entry is not None:
        return len(entry) == 1

    lazy_entry = _make_lazycache_entry(filename, module_globals)
    if lazy_entry is not None:
        cache[filename] = lazy_entry
        return True
    return False

def _validate_status(self, status):
    if _name_disallowed_re.search(status):
        raise ValueError("Control characters are not allowed in status")
    if len(status) < 4:
        raise AssertionError("Status must be at least 4 characters")
    if not status[:3].isdigit():
        raise AssertionError("Status message must begin w/3-digit code")
    if status[3] != " ":
        raise AssertionError("Status message must have a space after code")

