    if self.cdata_elem == 'plaintext':
        self.interesting = re.compile(r'\z')
    elif escapable and not self.convert_charrefs:
        self.interesting = re.compile(r'&|</%s(?=[\t\n\r\f />])' % self.cdata_elem,
                                      re.IGNORECASE|re.ASCII)
    else:
        self.interesting = re.compile(r'</%s(?=[\t\n\r\f />])' % self.cdata_elem,
                                      re.IGNORECASE|re.ASCII)

